def hash_bytes(path, max_bytes):
    if max_bytes == 0:
        return None
    h = hashlib.sha1()
    read = 0
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            read += len(chunk)
            if max_bytes and read > max_bytes:
                return None
            h.update(chunk)
    return h.hexdigest()

